python3 << 'PY'
import urllib.request, json, math

lat, lon = 12.727004, 78.173613

# Open-Elevation / OpenTopoData SRTM
url = f"https://api.opentopodata.org/v1/srtm30m?locations={lat},{lon}|{lat+0.02},{lon}|{lat-0.02},{lon}|{lat},{lon+0.02}|{lat},{lon-0.02}|{lat+0.03},{lon+0.02}|{lat-0.01},{lon-0.02}"
print("ELEV:", urllib.request.urlopen(url, timeout=30).read().decode()[:800])

# Overpass: nearby forests, roads, water
query = f'''
[out:json][timeout:25];
(
  way["natural"="water"](around:3000,{lat},{lon});
  way["waterway"](around:3000,{lat},{lon});
  way["landuse"="forest"](around:3000,{lat},{lon});
  way["natural"="wood"](around:3000,{lat},{lon});
  way["natural"="scrub"](around:3000,{lat},{lon});
  way["landuse"="farmland"](around:2000,{lat},{lon});
  way["highway"~"primary|secondary|tertiary|unclassified|track"](around:2000,{lat},{lon});
  node["place"~"village|hamlet"](around:3000,{lat},{lon});
);
out center tags;
'''
req = urllib.request.Request(
    "https://overpass-api.de/api/interpreter",
    data=query.encode(),
    headers={"Content-Type":"application/x-www-form-urlencoded"}
)
try:
    data = json.loads(urllib.request.urlopen(req, timeout=60).read())
    print("OSM elements:", len(data.get("elements",[])))
    from collections import Counter
    kinds = Counter()
    samples = []
    for e in data.get("elements",[]):
        tags = e.get("tags",{})
        key = tags.get("natural") or tags.get("landuse") or tags.get("waterway") or tags.get("highway") or tags.get("place") or "?"
        kinds[key]+=1
        if len(samples)<25:
            name = tags.get("name","")
            c = e.get("center") or {"lat":e.get("lat"),"lon":e.get("lon")}
            samples.append((key, name, c.get("lat"), c.get("lon")))
    print("kinds:", dict(kinds))
    for s in samples:
        print(s)
except Exception as ex:
    print("OSM error", ex)

# Simple Canadian FWI components approximation from daily weather
# Using Open-Meteo past 14 days to estimate FFMC/DMC qualitatively
import json as J
w = json.loads(urllib.request.urlopen(
    "https://api.open-meteo.com/v1/forecast?latitude=12.727&longitude=78.174&daily=temperature_2m_max,relative_humidity_2m_min,precipitation_sum,wind_speed_10m_max&timezone=Asia%2FKolkata&past_days=10&forecast_days=5"
).read())
print("\nFWI inputs next days:")
for t,tx,rh,p,ws in zip(w['daily']['time'], w['daily']['temperature_2m_max'], w['daily']['relative_humidity_2m_min'], w['daily']['precipitation_sum'], w['daily']['wind_speed_10m_max']):
    # crude danger: hot + dry + windy + no rain
    score = 0
    if tx>=32: score+=1
    if tx>=35: score+=1
    if rh is not None and rh<=40: score+=2
    elif rh is not None and rh<=55: score+=1
    if (p or 0)<1: score+=1
    if ws>=20: score+=1
    if ws>=25: score+=1
    label = ['Low','Mod','High','Very High','Extreme','Extreme+'][min(score,5)]
    print(t, f"Tmax={tx} RHmin={rh} precip={p} wind={ws} -> crude {label} ({score})")
