# Retry OSM with proper UA; get SRTM grid for risk surface; try NASA FIRMS country CSV
python3 << 'PY'
import urllib.request, json, ssl

lat, lon = 12.727004, 78.173613

# denser elevation grid ~4km around village
pts = []
for i in range(-4,5):
  for j in range(-4,5):
    pts.append(f"{lat+i*0.005},{lon+j*0.005}")
# API allows multiple; batch in chunks
elevs=[]
for k in range(0,len(pts),50):
  chunk="|".join(pts[k:k+50])
  url=f"https://api.opentopodata.org/v1/srtm30m?locations={chunk}"
  try:
    r=json.loads(urllib.request.urlopen(url,timeout=60).read())
    for res in r['results']:
      if res['elevation'] is not None:
        elevs.append((res['location']['lat'], res['location']['lng'], res['elevation']))
  except Exception as e:
    print('elev err', e)
if elevs:
  emin=min(elevs,key=lambda x:x[2]); emax=max(elevs,key=lambda x:x[2])
  print(f"n={len(elevs)} elev min={emin} max={emax}")
  # steepest local gradients (slope proxy)
  slopes=[]
  by = {(round(a,5), round(b,5)):e for a,b,e in elevs}
  for a,b,e in elevs:
    for da,db in [(0.005,0),(0,0.005)]:
      key=(round(a+da,5), round(b+db,5))
      if key in by:
        # rise/run ~ 0.005 deg ~ 555m
        slope=(by[key]-e)/555.0
        slopes.append((abs(slope), a,b,e, key[0], key[1], by[key]))
  slopes.sort(reverse=True)
  print('steepest slopes (abs rise/run):')
  for s in slopes[:8]:
    print(s)

# Overpass with User-Agent
query = f'''[out:json][timeout:25];
(
  way["natural"="water"](around:4000,{lat},{lon});
  relation["natural"="water"](around:4000,{lat},{lon});
  way["landuse"="reservoir"](around:4000,{lat},{lon});
  way["natural"="wood"](around:4000,{lat},{lon});
  way["landuse"="forest"](around:4000,{lat},{lon});
  way["natural"="scrub"](around:4000,{lat},{lon});
  way["natural"="grassland"](around:4000,{lat},{lon});
  node["place"](around:4000,{lat},{lon});
);
out center tags;'''
req=urllib.request.Request('https://overpass-api.de/api/interpreter', data=query.encode(), headers={'User-Agent':'EBTL-fire-risk-assessment/1.0','Content-Type':'application/x-www-form-urlencoded'})
try:
  data=json.loads(urllib.request.urlopen(req, timeout=90).read())
  print('OSM count', len(data['elements']))
  for e in data['elements'][:40]:
    tags=e.get('tags',{})
    c=e.get('center') or e
    print(e['type'], tags.get('name',''), tags.get('natural') or tags.get('landuse') or tags.get('place'), c.get('lat'), c.get('lon'))
except Exception as ex:
  print('OSM', ex)

# Try FIRMS via firms.modaps area API with empty key patterns / public page
for u in [
  'https://firms.modaps.eosdis.nasa.gov/data/active_fire/noaa-20-viirs-c2/csv/J1_VIIRS_C2_South_Asia_24h.csv',
  'https://firms.modaps.eosdis.nasa.gov/data/active_fire/suomi-npp-viirs-c2/csv/SUOMI_VIIRS_C2_South_Asia_24h.csv',
  'https://firms.modaps.eosdis.nasa.gov/data/active_fire/modis-c6.1/csv/MODIS_C6_1_South_Asia_24h.csv',
]:
  try:
    req=urllib.request.Request(u, headers={'User-Agent':'Mozilla/5.0'})
    txt=urllib.request.urlopen(req, timeout=60).read().decode()
    lines=txt.strip().splitlines()
    print('\n', u.split('/')[-1], 'lines', len(lines))
    hits=[]
    for line in lines[1:]:
      parts=line.split(',')
      try:
        la=float(parts[0]); lo=float(parts[1])
      except: continue
      if 12.4<=la<=13.1 and 77.8<=lo<=78.5:
        hits.append(line)
    print('hits near Krishnagiri:', len(hits))
    for h in hits[:15]: print(h)
  except Exception as e:
    print('FIRMS csv', u.split('/')[-1], e)
